INSERT INTO public.mistakes VALUES (123, '文字・語彙', '簡単に合格できると思ってあなどってはいけない。', '喜んで', '安心して', '軽くみて', '期待して', 3, NULL, 2, '2026-05-08 07:15:47.826076+00', '2026-05-02 06:05:24.010851+00', 'あなどって', '言い換え類義', '2026-05-08 07:21:04.507+00', 'JLPT N1 この一冊で合格', '126', NULL, NULL);
INSERT INTO public.mistakes VALUES (141, '文字・語彙', '彼女が嬉しそうにパンをほおばっている。', '選んで', '食べて', '買って', '眺めて', 2, NULL, 2, '2026-05-11 04:16:18.578856+00', '2026-05-02 06:05:24.010851+00', 'ほおばって', '言い換え類義', '2026-05-11 04:22:20.024+00', 'JLPT N1 この一冊で合格', '129', NULL, NULL);
INSERT INTO public.mistakes VALUES (185, '文法', '彼と大喧嘩（　）、一言も口を利いてくれなくなった。', 'をしてからというもの', 'に至るまで', 'をもって', 'ではあるまいし', 1, '【意味】Vてからというもの：自从V以来一直〜（過去のある時点を境に状態が継続）。
1. ✓ をしてからというもの：「大喧嘩をしてからというもの、口を利いてくれない」と自然な持続状態
2. ✗ に至るまで：「Nに至るまで」= 直到N（範囲の極限）、文脈不適
3. ✗ をもって：「Nをもって」= 用N／以N为限、ここでは時間の境界を示すには合わない
4. ✗ ではあるまいし：「〜じゃあるまいし」= 又不是…（理由提示）', 1, '2026-05-05 08:54:05.210512+00', '2026-05-05 08:54:05.210512+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '188', NULL, NULL);
INSERT INTO public.mistakes VALUES (186, '文法', '今年のオリンピック出場（　）、現役を引退することを決意した。', 'を押して', 'を込めて', 'を限りに', 'を皮切りに', 3, '【意味】Nを限りに：以N为最後／从N开始截止（終止時点の指定、=Nで終わる）。
1. ✗ を押して：「反対を押して」= 不顾反对地〜、文脈不適
2. ✗ を込めて：「気持ちを込めて」= 倾注感情、不適
3. ✓ を限りに：「今年の出場を限りに引退」= 以今年的奥运出场为最后一次，决定退役
4. ✗ を皮切りに：「Nを皮切りに」= 以N为开端（起点、Q9 と対義）', 1, '2026-05-05 08:54:05.210512+00', '2026-05-05 08:54:05.210512+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '188', NULL, NULL);
INSERT INTO public.mistakes VALUES (144, '文字・語彙', '発散', '一万円相当のお宝を発散するイベントに参加した。', '勉強のストレスを発散するには、飲み会が一番だ。', '日本語教育については、彼女が一番発散している。', '日本から全世界に事業を発散する予定だ。', 2, '【意味】発散：たまったものを外に放出すること、ストレスなどを解消すること。
1. ✗「お宝を発散する」→「お宝を配布する」
2. ✓ ストレスを発散する。
3. ✗「彼女が一番発散している」→「彼女が一番理解している」
4. ✗「事業を発散する」→「事業を拡大する」', 1, '2026-05-02 06:47:25.940549+00', '2026-05-02 06:47:25.940549+00', NULL, '用法', '2026-05-08 08:02:38.25+00', 'JLPT N1 この一冊で合格', '141', NULL, '["発散", "発散", "発散", "発散"]');
INSERT INTO public.mistakes VALUES (142, '文字・語彙', '由来', '「サボる」という言葉は、フランス語に由来している。', '人類の由来は、三十万年前にまでさかのぼる。', '日本では、年の初めに見る夢に富士山が出てくると由来が良いとされている。', 'この人物が今回の事件に由来している可能性は低そうだ。', 1, '【意味】由来：あるものが何に基づいて生じたか、その出所・始まり。
1. ✓「サボる」はフランス語の sabotage に由来している。
2. ✗「人類の由来」→「人類の起源」
3. ✗「由来が良い」→「縁起が良い」
4. ✗「事件に由来している」→「事件に関与している」', 1, '2026-05-02 06:47:25.940549+00', '2026-05-02 06:47:25.940549+00', NULL, '用法', '2026-05-08 08:02:24.22+00', 'JLPT N1 この一冊で合格', '140', NULL, '["由来", "由来", "由来", "由来"]');
INSERT INTO public.mistakes VALUES (146, '文字・語彙', '調達', '20歳の時に、運転免許を調達した。', '一か月以内に税金を納めるように役所から調達が来た。', '二日間かけて山を登り、ようやく山頂に調達した。', '会社をおこすための資金を調達しなければならない。', 4, '【意味】調達（ちょうたつ）：必要なもの（金・物資など）を集めて取りそろえること。
1. ✗「免許を調達する」→「免許を取得する」
2. ✗「役所から調達が来た」→「役所から通達が来た」
3. ✗「山頂に調達した」→「山頂に到達した」
4. ✓ 資金を調達する。', 3, '2026-05-02 07:35:17.009527+00', '2026-05-02 06:47:25.940549+00', NULL, '用法', '2026-05-08 07:45:02.974+00', 'JLPT N1 この一冊で合格', '141', NULL, '["調達", "調達", "調達", "調達"]');
INSERT INTO public.mistakes VALUES (143, '文字・語彙', '反発', '中学生の頃は、親によく反発していた。', '鏡に光が反発して、写真がうまく撮れなかった。', '新商品に対するお客様の反発は、予想より良かった。', '彼の身勝手な発言に、反発を抱いている。', 1, '【意味】反発：他から受ける力に逆らって押し返すこと、相手の言動に逆らうこと。
1. ✓ 親に反発（反抗）していた。
2. ✗「光が反発する」→「光が反射する」
3. ✗「お客様の反発（マイナスの反応の意味になる）」→「お客様の反応」
4. ✗「反発を抱く」とは言わない →「反感を抱く」', 2, '2026-05-02 06:49:18.638141+00', '2026-05-02 06:47:25.940549+00', NULL, '用法', '2026-05-08 08:02:13.566+00', 'JLPT N1 この一冊で合格', '140', NULL, '["反発", "反発", "反発", "反発"]');
INSERT INTO public.mistakes VALUES (148, '文法', '失敗をして ＿＿ ＿＿ ★ ＿＿ ことに意味があるということを忘れないでください。', '笑われようが', '何事も', '挑戦し続ける', 'どんなに', 2, '正しい並び: 4→1→2→3（どんなに→笑われようが→何事も→挑戦し続ける）
完成文: 失敗をしてどんなに笑われようが、何事も挑戦し続けることに意味がある…。
【ポイント】「どんなに〜（よ）うが」= 不管多么…也…（逆接の譲歩）。「何事も」は後半「挑戦し続ける」の主題。', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法2（文の組み立て）', '2026-05-03 06:24:08.479+00', 'JLPT N1 この一冊で合格', '171', NULL, NULL);
INSERT INTO public.mistakes VALUES (147, '文法', '相手は負けを知らない強豪チーム ＿＿ ★ ＿＿ ＿＿ だろう。', 'とはいえ', 'ではない', '勝てない相手', '今の私達なら', 4, '正しい並び: 1→4→3→2（とはいえ→今の私達なら→勝てない相手→ではない）
完成文: 相手は負けを知らない強豪チームとはいえ、今の私達なら勝てない相手ではないだろう。
【ポイント】「Nとはいえ」= 即使是N…（譲歩）。後半「勝てない相手ではない」=「勝てる相手だ」の二重否定。', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法2（文の組み立て）', '2026-05-03 06:24:24.533+00', 'JLPT N1 この一冊で合格', '171', NULL, NULL);
INSERT INTO public.mistakes VALUES (149, '文法', '夜更かしをしてしまい、今から寝（　）寝まいが、授業中に寝てしまうことに変わりはないだろう。', 'ようにも', 'ようが', 'ようで', 'ようなら', 2, '【意味】〜ようが〜まいが：不管…还是不…（譲歩・並列）
1. ✗ ようにも：「〜したくてもできない」、「まいが」とは並列しない
2. ✓ ようが：「寝ようが寝まいが」で行動の有無を問わず結果が同じ
3. ✗ ようで：そう見える／そうらしい
4. ✗ ようなら：もしそうであれば（条件）', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '169', NULL, NULL);
INSERT INTO public.mistakes VALUES (150, '文法', 'まだ新人（　）、仕事に対して無責任な言動を取ることは許されない。', 'かと思いきや', 'だとはいえ', 'というもの', 'ではあるまいし', 2, '【意味】〜とはいえ：即使…，但是…（譲歩）
1. ✗ かと思いきや：以为…结果…（意外な事態）
2. ✓ だとはいえ：「新人とはいえ無責任は許されない」と譲歩
3. ✗ というもの：「〜というものだ」で本質・道理を述べる
4. ✗ ではあるまいし：「〜じゃあるまいし」= 又不是…（理由を示す）', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '169', NULL, NULL);
INSERT INTO public.mistakes VALUES (151, '文法', '部長「伊藤くん、昨日会社のみんなで行った山登りはどうだったんだい。」伊藤「とても楽しかったです。普段運動をしていなかったので、今朝は筋肉痛で起き上が（　）起き上がれませんでしたよ。」', 'ろうにも', 'るまいが', 'ったところで', 'りようが', 1, '【意味】〜（よ）うにも〜ない：想…也…不了（やりたくても不可能な理由がある）
1. ✓ ろうにも：「起き上がろうにも起き上がれない」（筋肉痛で物理的に不可能）
2. ✗ るまいが：〜まいが〜まいが で並列譲歩、単独では不成立
3. ✗ ったところで：即使…也…（前提と矛盾）
4. ✗ りようが：意向形「〜（よ）うが」は連用形に付かない', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '169', NULL, NULL);
INSERT INTO public.mistakes VALUES (152, '文法', '山田「最近流行ってる感染症って怖いよね。」鈴木「うん。どんなに対策をして気を付け（　）避けられないのが怖いよね。」', 'ようが', 'つつ', 'たかと思いきや', 'たところを', 1, '【意味】どんなに〜（よ）うが：不管多么…也…（譲歩）
1. ✓ ようが：「気を付けようが避けられない」
2. ✗ つつ：〜しながら（同時動作・逆接）、「どんなに」と呼応しない
3. ✗ たかと思いきや：以为…结果…
4. ✗ たところを：ちょうど…の場面で（場面提示）', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '170', NULL, NULL);
INSERT INTO public.mistakes VALUES (153, '文法', 'いくら頑丈な鞄（　）、重いものを入れるとちぎれてしまいそうで不安になる。', 'にひきかえ', 'とあって', 'もさることながら', 'といえども', 4, '【意味】〜といえども：虽说是…但是…（書き言葉の譲歩、=とはいっても）
1. ✗ にひきかえ：与…相反（対比）
2. ✗ とあって：因为…这样的特殊情况
3. ✗ もさることながら：…自不必说，更…（累加）
4. ✓ といえども：「いくら頑丈な鞄といえども、重いと不安」と譲歩', 1, '2026-05-03 06:22:56.014998+00', '2026-05-03 06:22:56.014998+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '170', NULL, NULL);
INSERT INTO public.mistakes VALUES (154, '文字・語彙', '駅前の店はどこも繁盛している。', 'びんしょう', 'びんじょう', 'はんしょう', 'はんじょう', 4, '【意味】繁盛(はんじょう)：商売がうまくいき、客や利益が多く集まること。
1. ✗ びんしょう：誤読
2. ✗ びんじょう：「便乗」の読み
3. ✗ はんしょう：「繁昌」を「はんしょう」と読むのは慣用外
4. ✓ はんじょう：「繁(はん)＋盛(じょう)」', 1, '2026-05-04 06:16:48.292864+00', '2026-05-04 06:16:48.292864+00', '繁盛', '漢字読み', NULL, 'JLPT N1 2010年7月 真題', '問題1-1', NULL, NULL);
INSERT INTO public.mistakes VALUES (155, '文字・語彙', 'この春、とうとう（　）のマイホームを手に入れた。', '切望', '欲望', '念願', '志願', 3, '【ポイント】「念願の〜を手に入れる／叶える」が定型コロケーション。
1. ✗ 切望：強く望むこと。動詞的「〜を切望する」が普通で、連体修飾「切望のN」は不自然
2. ✗ 欲望：欲しがる感情。マイホーム獲得の文脈には合わない
3. ✓ 念願：長年抱き続けた願い。「念願のマイホーム」が定番表現
4. ✗ 志願：自ら進んで申し出ること（学校・職務など）', 1, '2026-05-04 06:16:48.292864+00', '2026-05-04 06:16:48.292864+00', NULL, '文脈規定', NULL, 'JLPT N1 2010年7月 真題', '問題2-9', NULL, NULL);
INSERT INTO public.mistakes VALUES (156, '文字・語彙', '会議ではA案に賛成したが、（　）を言えばB案の方がいいと思う。', '本音', '本気', '弱音', '弱気', 1, '【ポイント】「本音を言えば」= 实话说／本心としては。表向き（建前）と対比される定型表現。
1. ✓ 本音：本心・建前と対の語
2. ✗ 本気：真剣であるさま（「本気で言う／取り組む」）
3. ✗ 弱音：弱気な発言。「弱音を吐く」が定型で「言えば」とは結びにくい
4. ✗ 弱気：気が弱いこと。形容動詞的で「を言えば」と結ばない', 1, '2026-05-04 06:16:48.292864+00', '2026-05-04 06:16:48.292864+00', NULL, '文脈規定', NULL, 'JLPT N1 2010年7月 真題', '問題2-10', NULL, NULL);
INSERT INTO public.mistakes VALUES (157, '文字・語彙', '先方に協力を依頼したが、（　）断られてしまった。', 'しんなり', 'やんわり', 'うんざり', 'ひんやり', 2, '【ポイント】「やんわり断る」=「角を立てず婉曲に断る」の定型表現。
1. ✗ しんなり：野菜などがしおれて柔らかくなる様。人の言動には使わない
2. ✓ やんわり：物腰が柔らかく婉曲なさま
3. ✗ うんざり：飽き飽きして嫌になる感情
4. ✗ ひんやり：気温・物に触れた時の冷たい感触', 1, '2026-05-04 06:16:48.292864+00', '2026-05-04 06:16:48.292864+00', NULL, '文脈規定', NULL, 'JLPT N1 2010年7月 真題', '問題2-11', NULL, NULL);
INSERT INTO public.mistakes VALUES (158, '文字・語彙', '彼はお金に関してルーズなところがある。', 'ずうずうしい', 'だらしない', 'うるさい', 'よわい', 2, '【意味】ルーズ(loose)：締まりがない、いい加減なさま。
1. ✗ ずうずうしい：厚かましい
2. ✓ だらしない：締まりがない・整っていない（金銭面の「ルーズ」と同義）
3. ✗ うるさい：細かいことに口を出す／喧しい
4. ✗ よわい：弱い', 3, '2026-05-11 04:21:09.835668+00', '2026-05-04 06:22:01.131272+00', 'ルーズ', '言い換え類義', '2026-05-11 04:23:00.272+00', 'JLPT N1 2010年7月 真題', '問題3-14', NULL, NULL);
INSERT INTO public.mistakes VALUES (205, '文字・語彙', '人口が減る一方だった地方に工場を（　）し、地域の活性化を試みる。', '誘惑', '弁償', '持参', '誘致', 4, '【ポイント】誘致(ゆうち)：招商、引进（企業・施設・大会などを呼び込む）。
1. ✗ 誘惑：诱惑（人を悪い方向に引き付ける）
2. ✗ 弁償：赔偿（損害を補償する）
3. ✗ 持参：自带（物を持って参上する）
4. ✓ 誘致：「工場を誘致する」「オリンピックを誘致する」が定型', 1, '2026-05-08 06:56:33.03458+00', '2026-05-08 06:56:33.03458+00', NULL, '文脈規定', NULL, 'JLPT N1 この一冊で合格', '105', NULL, NULL);
INSERT INTO public.mistakes VALUES (163, '文法', '部屋の広さも考えず、店員に勧められる（　）、大きいテーブルを買ってしまった。', 'まま', 'ままを', 'ままでも', 'ままなのに', 1, '【意味】〜まま：状態をそのままに、その勢いで（成り行き任せ）。
1. ✓ まま：「勧められるまま」=言われるがままに、判断を挟まず
2. ✗ ままを：「ままを」は対象を取る限定構文で文脈不適
3. ✗ ままでも：「〜のままでも」=現状維持の譲歩、文脈不適
4. ✗ ままなのに：「のに」は逆接、後文と整合しない', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-27', NULL, NULL);
INSERT INTO public.mistakes VALUES (164, '文法', 'A会社の元社員が１１日、突然の解雇を不当（　）、解雇取り消しを同社に求める訴えを起こした。', 'となって', 'になって', 'として', 'にして', 3, '【意味】〜として：認定・資格を表す。「Nを A として〜する」= NをAだと位置づけて〜する。
1. ✗ となって：「N となる」は変化／結果。判定文脈に合わない
2. ✗ になって：上に同じ
3. ✓ として：「不当として訴える」=不当だと主張して訴える（定型）
4. ✗ にして：時期・段階／並列を表す。判断の認定には使わない', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-28', NULL, NULL);
INSERT INTO public.mistakes VALUES (165, '文法', '間違い電話をかけてきて謝りもしないとは、失礼（　）。', 'でならない', 'ではいられない', '極まりない', 'に越したことはない', 3, '【意味】〜極まりない：きわめて〜だ（程度の最上級、書き言葉的）。形容動詞の語幹に直接接続。
1. ✗ でならない：自然と〜してしまう（感情の自発）「悲しくてならない」など
2. ✗ ではいられない：〜のままではいられない（状態維持の否定）
3. ✓ 極まりない：「失礼極まりない」= 极其失礼
4. ✗ に越したことはない：〜のが一番だ（最善策の提示）', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-30', NULL, NULL);
INSERT INTO public.mistakes VALUES (166, '文法', '（電車の中で）A「いつもならこの時間帯は込んでるのに、今日は空いてるね。」B「祝日だからね。」A「あ、そっか。どうりで空いてる（　）。」', 'こともある', 'に決まってる', 'に違いない', 'はずだ', 4, '【意味】どうりで〜はずだ：道理で〜なわけだ（原因が分かって納得する定型呼応）。
1. ✗ こともある：時々はある（頻度）、納得の表現ではない
2. ✗ に決まってる：強い断定、「どうりで」と呼応しない
3. ✗ に違いない：話者の推量、目の前の事実に対して使わない
4. ✓ はずだ：原因が判明した上での「なるほど納得」', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-31', NULL, NULL);
INSERT INTO public.mistakes VALUES (167, '文法', '今回の事件で山田氏の政治的影響力が完全に失われる（　）、弱まることは間違いないだろう。', 'ことはないにしても', 'ことはないにもかかわらず', 'ほかはないにしても', 'ほかはないにもかかわらず', 1, '【意味】〜ことはないにしても：たとえ〜することはないとしても（譲歩）。
1. ✓ ことはないにしても：「完全に失われることはないにしても、弱まる」と前後が逆接で整合
2. ✗ ことはないにもかかわらず：「〜ないのに」過去事実への逆接で文脈に合わない
3. ✗ ほかはないにしても：「〜するほかない」(=しか方法がない) は本文と意味矛盾
4. ✗ ほかはないにもかかわらず：上に同じ＋逆接の組み合わせで不適', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-32', NULL, NULL);
INSERT INTO public.mistakes VALUES (168, '文法', '「3歳までの育児は母親がすべきだ」と言う人もいるが、子育てをするのが母親で（　）、必ずしもそうではないと思う。', 'なくてはならないからといって', 'なくてはならないかというと', 'あるわけにはいかないからといって', 'あるわけにはいかないかというと', 2, '【意味】〜かというと、必ずしもそうではない：是不是〜呢，未必如此（否定的反問の定型）。
1. ✗ からといって：「〜だからといって…とは限らない」型、後文と呼応しにくい
2. ✓ なくてはならないかというと：「母親でなくてはならないか…必ずしもそうではない」と完全呼応
3. ✗ あるわけにはいかない：「いてはいけない」の意で文脈と矛盾
4. ✗ 同上＋〜かというと：意味的に成立しない', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-33', NULL, NULL);
INSERT INTO public.mistakes VALUES (206, '文字・語彙', '両親が事故にあったと聞いて、激しく（　）した。', '予言', '起動', '動揺', '暴動', 3, '【ポイント】動揺(どうよう)：心情の动摇、慌乱不安。「激しく動揺する」が定型コロケーション。
1. ✗ 予言：预言（未来の予測）
2. ✗ 起動：启动（機械を作動させる）
3. ✓ 動揺：「事故の知らせを聞いて激しく動揺」と感情の揺れに合致
4. ✗ 暴動：暴乱（集団的な実力行使）', 1, '2026-05-08 06:57:41.377933+00', '2026-05-08 06:57:41.377933+00', NULL, '文脈規定', NULL, 'JLPT N1 この一冊で合格', '106', NULL, NULL);
INSERT INTO public.mistakes VALUES (162, '文字・語彙', 'ある日、我が家に朗報が届いた。', '意外な知らせ', 'うれしい知らせ', '大切な知らせ', 'めずらしい知らせ', 2, '【意味】朗報(ろうほう)：明るく喜ばしい知らせ。「朗」は明るい意。対義語は「悲報」「凶報」。
1. ✗ 意外な知らせ：予想外、感情の方向性は問わない
2. ✓ うれしい知らせ：喜ばしい知らせ＝朗報
3. ✗ 大切な知らせ：重要、感情の方向性とは別
4. ✗ めずらしい知らせ：珍奇、頻度の話', 1, '2026-05-04 06:23:54.750129+00', '2026-05-04 06:23:54.750129+00', '朗報', '言い換え類義', '2026-05-11 03:56:39.003+00', 'JLPT N1 2010年7月 真題', '問題3-17', NULL, NULL);
INSERT INTO public.mistakes VALUES (161, '文字・語彙', 'あの兄弟はいつもお互いに張り合っている。', '競争して', '応援して', '無視して', '尊重して', 1, '【意味】張り合う(はりあう)：互いに負けまいと競い合う。
1. ✓ 競争して：勝ち負けを争う、同義
2. ✗ 応援して：助けて励ます
3. ✗ 無視して：相手にしない
4. ✗ 尊重して：価値を認めて重んじる', 1, '2026-05-04 06:23:54.750129+00', '2026-05-04 06:23:54.750129+00', '張り合っている', '言い換え類義', '2026-05-11 04:17:05.403+00', 'JLPT N1 2010年7月 真題', '問題3-16', NULL, NULL);
INSERT INTO public.mistakes VALUES (169, '文法', '先日提出した私の意見書は、単に決定に至るプロセスの問題点を指摘（　）、決定そのものに反対するものではありません。', 'しそうになったにすぎず', 'しそうになったほどで', 'しようとしたにすぎず', 'しようとしたほどで', 3, '【意味】〜（し）ようとしたにすぎない：单单是想〜而已（控えめな意図表明）。
1. ✗ しそうになったにすぎず：「しそうになる」=危うく〜しかける、意図的行為の文脈に不適
2. ✗ しそうになったほどで：「ほどで」は程度提示、後文と整合しない
3. ✓ しようとしたにすぎず：「指摘しようとしたにすぎず、反対するものではない」と謙抑表現で完璧呼応
4. ✗ しようとしたほどで：「ほどで」が後文と整合しない', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 2010年7月 真題', '問題5-35', NULL, NULL);
INSERT INTO public.mistakes VALUES (170, '文法', 'A「申し訳ない。僕が ＿＿ ＿＿ ★ ＿＿ ことになってしまって。」B「あ、いいえ、気にしないでください。」', '残業してもらう', '君にまで', 'ミスをした', 'ばかりに', 2, '正しい並び: 3→4→2→1（ミスをした→ばかりに→君にまで→残業してもらう）
完成文: 僕がミスをしたばかりに君にまで残業してもらうことになってしまって。
【ポイント】「Vたばかりに」=正因为〜（招致悪い結果の原因）。「君にまで」は予期せぬ波及範囲。', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法2（文の組み立て）', NULL, 'JLPT N1 2010年7月 真題', '問題6-37', NULL, NULL);
INSERT INTO public.mistakes VALUES (171, '文法', 'そもそもこの情報が、責任者である彼に ＿＿ ＿＿ ★ ＿＿ と思う。', '伝わっていない', 'おかしい', 'こと', 'からして', 4, '正しい並び: 1→3→4→2（伝わっていない→こと→からして→おかしい）
完成文: そもそもこの情報が、責任者である彼に伝わっていないことからしておかしいと思う。
【ポイント】「Nからして」=连〜都〜（極端な例の提示）。「VことからしてA」で「〜という事実からしてAだ」。', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法2（文の組み立て）', NULL, 'JLPT N1 2010年7月 真題', '問題6-38', NULL, NULL);
INSERT INTO public.mistakes VALUES (172, '文法', 'アルバイト先の仲間は、みんな ＿＿ ＿＿ ★ ＿＿ 話でいつも盛り上がっています。', 'こともあって', 'ならではの', '同世代', '年が近い', 3, '正しい並び: 4→1→3→2（年が近い→こともあって→同世代→ならではの）
完成文: みんな年が近いこともあって、同世代ならではの話でいつも盛り上がっています。
【ポイント】「Nならではの」= 〜にしか出せない／〜独特の。前段で同世代である理由を示し、後段で同世代固有の話題に繋ぐ。', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法2（文の組み立て）', NULL, 'JLPT N1 2010年7月 真題', '問題6-39', NULL, NULL);
INSERT INTO public.mistakes VALUES (173, '文法', 'ジョン「この『りかい』という言葉はどういう意味ですか。」アリ「ああ、確か『わかる』 ＿＿ ★ ＿＿ ＿＿ んですけど。」', 'ような', 'と思う', 'という', '意味だった', 4, '正しい並び: 3→4→1→2（という→意味だった→ような→と思う）
完成文: 確か『わかる』という意味だったような と思うんですけど。
【ポイント】「〜という意味だ」=〜という意味である。「〜ような気がする／と思う」で曖昧な記憶を表す。', 1, '2026-05-04 06:36:12.681184+00', '2026-05-04 06:36:12.681184+00', NULL, '文の文法2（文の組み立て）', NULL, 'JLPT N1 2010年7月 真題', '問題6-40', NULL, NULL);
INSERT INTO public.mistakes VALUES (187, '文法', '（アナウンサー）「来月フランス（　）、日本を含む世界10か国で順次にピカソの展覧会を開催することが発表されました。」', 'をもって', 'を限りに', 'を皮切りに', 'をめぐって', 3, '【意味】Nを皮切りに：以N为开端，接连…（事件の連鎖の起点）。
1. ✗ をもって：「Nをもって」= 用N／以N为限（終止）、起点提示には合わない
2. ✗ を限りに：「Nを限りに」= 以N为最後（終点、Q6 と対義）
3. ✓ を皮切りに：「フランスを皮切りに世界10か国で順次開催」= 以法国为开端，依次在10国展开
4. ✗ をめぐって：「Nをめぐって」= 围绕N（議論・話題の対象）', 1, '2026-05-05 08:54:05.210512+00', '2026-05-05 08:54:05.210512+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '189', NULL, NULL);
INSERT INTO public.mistakes VALUES (188, '文法', '私が10年以上応援してきた ＿＿ ★ ＿＿ ＿＿ 休止してしまうそうだ。', 'もって', '活動を', 'アイドルグループは', '今年を', 4, '正しい並び: 3→4→1→2（アイドルグループは→今年を→もって→活動を）
完成文: 私が10年以上応援してきたアイドルグループは今年をもって活動を休止してしまうそうだ。
【ポイント】「Nをもって」= 以N为限／用N（終止時点を明示）。「今年をもって…休止」で「截至今年（此后）停止活動」。', 1, '2026-05-05 08:54:05.210512+00', '2026-05-05 08:54:05.210512+00', NULL, '文の文法2（文の組み立て）', NULL, 'JLPT N1 この一冊で合格', '190', NULL, NULL);
INSERT INTO public.mistakes VALUES (208, '文字・語彙', '大勢の前で自分の意見を主張するには、度胸が必要だ。', '勇気', '信頼', '忍耐', '地位', 1, '【意味】度胸(どきょう)：胆量、勇气（怖がらない強い心）。
1. ✓ 勇気：勇气（同義）
2. ✗ 信頼：信任
3. ✗ 忍耐：忍耐
4. ✗ 地位：地位', 1, '2026-05-08 07:04:12.93975+00', '2026-05-08 07:04:12.93975+00', '度胸', '言い換え類義', '2026-05-11 03:56:17.29+00', 'JLPT N1 この一冊で合格', '131', NULL, NULL);
INSERT INTO public.mistakes VALUES (207, '文字・語彙', '友人と好きな異性の仕草について、朝まで語り合った。', '性格', '声', '顔', '動作', 4, '【意味】仕草(しぐさ)：举止、小动作（体や手の動かし方）。
1. ✗ 性格：性格（内面）
2. ✗ 声：声音
3. ✗ 顔：脸（外貌）
4. ✓ 動作：动作（仕草と同義）', 1, '2026-05-08 07:04:12.93975+00', '2026-05-08 07:04:12.93975+00', '仕草', '言い換え類義', '2026-05-11 03:56:58.229+00', 'JLPT N1 この一冊で合格', '131', NULL, NULL);
INSERT INTO public.mistakes VALUES (209, '文字・語彙', '美しい景色が脳裏に焼き付いている。', '歴史', '記憶', '映像', '写真', 2, '【意味】脳裏(のうり)：脑海、心中（記憶の場）。「脳裏に焼き付く」=深深印在脑海中。
1. ✗ 歴史：历史
2. ✓ 記憶：「脳裏に焼き付く」=「記憶に焼き付く」と同義
3. ✗ 映像：影像（媒体）
4. ✗ 写真：照片', 1, '2026-05-08 07:04:12.93975+00', '2026-05-08 07:04:12.93975+00', '脳裏', '言い換え類義', '2026-05-11 04:16:28.293+00', 'JLPT N1 この一冊で合格', '131', NULL, NULL);
INSERT INTO public.mistakes VALUES (211, '文字・語彙', '日本語能力試験に合格できたのは、ただのまぐれだ。', '必然', '実力', '夢物語', '偶然', 4, '【意味】紛れ(まぐれ)：侥幸、碰巧（偶然のなりゆき）。「まぐれ当たり」など。
1. ✗ 必然：必然（反義）
2. ✗ 実力：实力（反義）
3. ✗ 夢物語：白日梦／空想
4. ✓ 偶然：偶然（同義）', 1, '2026-05-08 07:04:12.93975+00', '2026-05-08 07:04:12.93975+00', 'まぐれ', '言い換え類義', '2026-05-11 04:18:28.485+00', 'JLPT N1 この一冊で合格', '131', NULL, NULL);
INSERT INTO public.mistakes VALUES (189, '文字・語彙', 'アルバイトをして、生活費を賄う必要がある。', 'まかなう', 'あらがう', 'こう', 'たまう', 1, '【意味】賄う(まかなう)：维持／筹措（必要なものを工面する）。「賄賂(わいろ)」も同字。
1. ✓ まかなう
2. ✗ あらがう=「抗う」（抵抗）
3. ✗ こう=「請う／乞う」（请求）
4. ✗ たまう=「賜う」（赐予、敬語）', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '賄う', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '95', NULL, NULL);
INSERT INTO public.mistakes VALUES (190, '文字・語彙', 'あまりにも早すぎる親友の死を、心から嘆く。', 'なげく', 'おどろく', 'まねく', 'くじく', 1, '【意味】嘆く(なげく)：悲伤、哀叹。「嘆息」「悲嘆」など。
1. ✓ なげく
2. ✗ おどろく=「驚く」
3. ✗ まねく=「招く」
4. ✗ くじく=「挫く」（挫败、扭伤）', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '嘆く', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '95', NULL, NULL);
INSERT INTO public.mistakes VALUES (191, '文字・語彙', '日本代表としての責任を感じながら、試合に臨む。', 'はげむ', 'いどむ', 'ひそむ', 'のぞむ', 4, '【意味】臨む(のぞむ)：面对（重大場面に出席する）。「臨時／臨床」と同字。「望む」と同訓だが意味は別。
1. ✗ はげむ=「励む」（勤勉努力）
2. ✗ いどむ=「挑む」（挑战）
3. ✗ ひそむ=「潜む」（潜伏）
4. ✓ のぞむ', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '臨む', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '95', NULL, NULL);
INSERT INTO public.mistakes VALUES (192, '文字・語彙', '可愛いものを見ると心が癒される。', 'さとされる', 'いやされる', 'はなされる', 'みたされる', 2, '【意味】癒す(いやす)：治愈、抚慰。「治癒」「癒着」と同字。
1. ✗ さとす=「諭す」（开导）
2. ✓ いやされる
3. ✗ はなす=「放す／離す／話す」
4. ✗ みたす=「満たす」（充满）', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '癒される', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '96', NULL, NULL);
INSERT INTO public.mistakes VALUES (193, '文字・語彙', '少子高齢化に対して、政府が新たな策を施す。', 'ほどす', 'ほかす', 'ほどかす', 'ほどこす', 4, '【意味】施す(ほどこす)：施加、实施。「施策／実施／施工」など音読みは「し」。
1. ✗ ほどす：実在しない読み
2. ✗ ほかす：方言で「捨てる」、ここでは不適
3. ✗ ほどかす：実在しない読み
4. ✓ ほどこす', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '施す', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '96', NULL, NULL);
INSERT INTO public.mistakes VALUES (181, '文法', '中本「なんだか最近物事がうまくいかない気がするんです。」先輩「そんな風に見えないけどな。中本さんはきっと真面目である（　）そう感じちゃうんだね。」', 'こととて', 'がゆえに', '手前', 'ことだから', 2, '【意味】Aがゆえに：正因为A，所以〜（書き言葉的な原因・理由）。
1. ✗ こととて：「Nのこととて」=〜だから（謝罪・告知の常套句）。形容動詞「真面目である」には接続しにくい
2. ✓ がゆえに：「真面目であるがゆえにそう感じてしまう」=正因为认真，才会有这种感觉
3. ✗ 手前：「Vた手前」=既然〜了的份上、文脈不適
4. ✗ ことだから：「Nのことだから」=因为是N那种人（人物の性格を理由にする）、ここでは状態「真面目である」と接続不自然', 1, '2026-05-04 11:42:46.206882+00', '2026-05-04 11:42:46.206882+00', NULL, '文の文法1（文法形式の判断）', NULL, 'JLPT N1 この一冊で合格', '174', NULL, NULL);
INSERT INTO public.mistakes VALUES (194, '文字・語彙', '「田中さん」がクラスに10人もいるので、本当に紛らわしい。', 'まじらわしい', 'まだらわしい', 'まぎらわしい', 'まどらわしい', 3, '【意味】紛らわしい(まぎらわしい)：容易混淆，难以区分。動詞「紛れる(まぎれる)／紛らす(まぎらす)」と同源。
1. ✗ まじらわしい：誤読（混じる→混じらわしい は不存在）
2. ✗ まだらわしい：誤読
3. ✓ まぎらわしい
4. ✗ まどらわしい：「まどろむ」と混同しがち', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '紛らわしい', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '96', NULL, NULL);
INSERT INTO public.mistakes VALUES (195, '文字・語彙', '漢字を2000個も覚えるのは本当に煩わしい。', 'まぎらわしい', 'わずらわしい', 'わざわざしい', 'けがらわしい', 2, '【意味】煩わしい(わずらわしい)：麻烦、烦琐。動詞「煩う(わずらう)」と同源。「煩雑／煩悩」も同字。
1. ✗ まぎらわしい=「紛らわしい」（容易混淆、Q8 と対比）
2. ✓ わずらわしい
3. ✗ わざわざしい：実在しない
4. ✗ けがらわしい=「汚らわしい」（肮脏、卑鄙）', 1, '2026-05-08 06:46:08.259633+00', '2026-05-08 06:46:08.259633+00', '煩わしい', '漢字読み', NULL, 'JLPT N1 この一冊で合格', '96', NULL, NULL);
INSERT INTO public.mistakes VALUES (130, '文字・語彙', '今回の研究結果は、歴史をくつがえすような発見だ。', '巻き込む', '肯定する', '繰り返す', 'ひっくり返す', 4, NULL, 1, '2026-05-02 06:05:24.010851+00', '2026-05-02 06:05:24.010851+00', 'くつがえす', '言い換え類義', '2026-05-08 07:15:22.381+00', 'JLPT N1 この一冊で合格', '127', NULL, NULL);
INSERT INTO public.mistakes VALUES (216, '文字・語彙', '仕事をたくさんこなすことは、とてもしんどい。', '気持ちがいい', '疲れる', '嬉しい', '忙しい', 2, '【意味】しんどい：累、辛苦（疲労感、関西弁起源で全国に普及）。
