4. ✗ 連帯感：团结意识', 1, '2026-05-08 07:04:12.93975+00', '2026-05-08 07:04:12.93975+00', '飲み込み', '言い換え類義', '2026-05-11 04:17:25.752+00', 'JLPT N1 この一冊で合格', '132', NULL, NULL);
INSERT INTO public.mistakes VALUES (214, '文字・語彙', '昨日クラスで、何かいざこざがあったらしい。', 'クレーム', 'サプライズ', 'イベント', 'トラブル', 4, '【意味】いざこざ：纠纷、争执（人間関係の小さな揉め事）。
