4. ✗ 目録：詳細な品目リスト', 1, '2026-05-08 06:50:48.487754+00', '2026-05-08 06:50:48.487754+00', NULL, '文脈規定', NULL, 'JLPT N1 この一冊で合格', '103', NULL, NULL);
INSERT INTO public.mistakes VALUES (198, '文字・語彙', '人がたくさん来ることを（　）に置いて準備する。', '先頭', '中腹', '念頭', '上腕', 3, '【ポイント】「Nを念頭に置く」= 把N放在心上、预先考虑到（定型）。
